<?php
namespace App\Http\Controllers;
use App\Http\Requests\{SaveInspeksiMobilRequest,StoreOfferMobilRequest};use App\Models\PengajuanMobil;use App\Services\{BookingMobilService,PengajuanMobilService};use Illuminate\Http\Request;use Throwable;
class OperationsPengajuanMobilController extends Controller { public function index(Request $r){$q=PengajuanMobil::with(['pelanggan','inspeksi'])->latest();if($r->filled('status'))$q->where('status',$r->string('status'));return view('operations.pengajuan-mobil.index',['rows'=>$q->paginate(20)->withQueryString()]);}public function show(PengajuanMobil $pengajuan_mobil){$pengajuan_mobil->load(['pelanggan','kendaraan','inspeksi.petugas']);return view('operations.pengajuan-mobil.show',['submission'=>$pengajuan_mobil]);}public function process(PengajuanMobil $p,PengajuanMobilService $svc){try{$svc->process($p->id_pengajuan);return back()->with('success','Pengajuan masuk antrean inspeksi.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}public function start(Request $r,PengajuanMobil $p,PengajuanMobilService $svc){try{$svc->startInspection($p->id_pengajuan,(int)(app(BookingMobilService::class)->actorPetugasId($r->user()->id_user)),(int)$r->validate(['kilometer'=>'required|integer|min:0'])['kilometer']);return back()->with('success','Inspeksi dimulai.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}public function inspection(SaveInspeksiMobilRequest $r,PengajuanMobil $p,PengajuanMobilService $svc){try{$svc->saveInspection($p->id_pengajuan,$r->validated(),(int)app(BookingMobilService::class)->actorPetugasId($r->user()->id_user));return back()->with('success','Hasil inspeksi disimpan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}public function offer(StoreOfferMobilRequest $r,PengajuanMobil $p,PengajuanMobilService $svc){try{$svc->offer($p->id_pengajuan,(string)$r->validated()['harga_penawaran']);return back()->with('success','Penawaran tersimpan.');}catch(Throwable $e){return back()->withErrors($e->getMessage());}}}
